FeatureScript 3083;
import(path : "onshape/std/common.fs", version : "3083.0");

// Generated by fsgen (paste export). Paste into a Feature Studio, then add the feature
// to a Part Studio from the toolbar. Parameters appear in the feature dialog.

// Midpoint of an arc from its endpoints; k = tan(sweep / 4) keeps the arc's sweep when parameters change.
function arcMid(a is Vector, b is Vector, k is number) returns Vector
{
    var d = b - a;
    return (a + b) / 2 + vector(d[1], -d[0]) * (k / 2);
}

annotation { "Feature Type Name" : "Tap collar" }
export const tapCollar = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Collar depth" }
        isLength(definition.collarDepth, { (millimeter) : [0, 17, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Bore diameter" }
        isLength(definition.boreDiameter, { (millimeter) : [0, 25.5, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Ring diameter" }
        isLength(definition.ringDiameter, { (millimeter) : [0, 33.5, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Block width" }
        isLength(definition.blockWidth, { (millimeter) : [0, 25.4, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Block height" }
        isLength(definition.blockHeight, { (millimeter) : [0, 24.5, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Plate thickness" }
        isLength(definition.plateThickness, { (millimeter) : [0, 1.2, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Plate top" }
        isLength(definition.plateTop, { (millimeter) : [0, 53.35, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Solenoid height" }
        isLength(definition.solenoidHeight, { (millimeter) : [0, 41, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Plate hole diameter" }
        isLength(definition.plateHoleDiameter, { (millimeter) : [0, 3.2, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Tap hole diameter" }
        isLength(definition.tapHoleDiameter, { (millimeter) : [0, 6.9, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Ear length" }
        isLength(definition.earLength, { (millimeter) : [0, 26, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Ear height" }
        isLength(definition.earHeight, { (millimeter) : [0, 13.8, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Split width" }
        isLength(definition.splitWidth, { (millimeter) : [0, 2.2, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Clamp hole offset" }
        isLength(definition.clampHoleOffset, { (millimeter) : [0, 20.2, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Clamp hole diameter" }
        isLength(definition.clampHoleDiameter, { (millimeter) : [0, 3.4, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Tab length" }
        isLength(definition.tabLength, { (millimeter) : [0, 19.95, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Tab height" }
        isLength(definition.tabHeight, { (millimeter) : [0, 10.8, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Pocket diameter" }
        isLength(definition.pocketDiameter, { (millimeter) : [0, 10.5, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Pocket depth" }
        isLength(definition.pocketDepth, { (millimeter) : [0, 2.5, 10000] } as LengthBoundSpec);
    }
    {
    // Collar sketch
    var collarSketchSk = newSketchOnPlane(context, id + "collarSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skCircle(collarSketchSk, "ring", { "center" : vector(0, 0) * millimeter, "radius" : definition.ringDiameter / 2 });
    skLineSegment(collarSketchSk, "block_bottom", { "start" : vector(-definition.blockWidth / 2, (0 * millimeter)), "end" : vector(definition.blockWidth / 2, (0 * millimeter)) });
    skLineSegment(collarSketchSk, "block_right", { "start" : vector(definition.blockWidth / 2, (0 * millimeter)), "end" : vector(definition.blockWidth / 2, definition.blockHeight) });
    skLineSegment(collarSketchSk, "block_top", { "start" : vector(definition.blockWidth / 2, definition.blockHeight), "end" : vector(-definition.blockWidth / 2, definition.blockHeight) });
    skLineSegment(collarSketchSk, "block_left", { "start" : vector(-definition.blockWidth / 2, definition.blockHeight), "end" : vector(-definition.blockWidth / 2, (0 * millimeter)) });
    skLineSegment(collarSketchSk, "ear_bottom", { "start" : vector(-definition.earLength, -definition.earHeight / 2), "end" : vector((0 * millimeter), -definition.earHeight / 2) });
    skLineSegment(collarSketchSk, "ear_right", { "start" : vector((0 * millimeter), -definition.earHeight / 2), "end" : vector((0 * millimeter), definition.earHeight / 2) });
    skLineSegment(collarSketchSk, "ear_top", { "start" : vector((0 * millimeter), definition.earHeight / 2), "end" : vector(-definition.earLength, definition.earHeight / 2) });
    skLineSegment(collarSketchSk, "ear_left", { "start" : vector(-definition.earLength, definition.earHeight / 2), "end" : vector(-definition.earLength, -definition.earHeight / 2) });
    skLineSegment(collarSketchSk, "tab_bottom", { "start" : vector((0 * millimeter), -definition.tabHeight / 2), "end" : vector(definition.tabLength, -definition.tabHeight / 2) });
    skLineSegment(collarSketchSk, "tab_right", { "start" : vector(definition.tabLength, -definition.tabHeight / 2), "end" : vector(definition.tabLength, definition.tabHeight / 2) });
    skLineSegment(collarSketchSk, "tab_top", { "start" : vector(definition.tabLength, definition.tabHeight / 2), "end" : vector((0 * millimeter), definition.tabHeight / 2) });
    skLineSegment(collarSketchSk, "tab_left", { "start" : vector((0 * millimeter), definition.tabHeight / 2), "end" : vector((0 * millimeter), -definition.tabHeight / 2) });
    skSolve(collarSketchSk);
    // Collar
    opExtrude(context, id + "collar" + "tool", { "entities" : qSketchRegion(id + "collarSketch"), "direction" : vector(-0, 1, -0), "endBound" : BoundingType.BLIND, "endDepth" : definition.collarDepth });
    // Solenoid plate sketch
    var solenoidPlateSketchSk = newSketchOnPlane(context, id + "solenoidPlateSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skLineSegment(solenoidPlateSketchSk, "plate_bottom", { "start" : vector(definition.collarDepth - definition.plateThickness, definition.blockHeight - (0.5 * millimeter)), "end" : vector(definition.collarDepth, definition.blockHeight - (0.5 * millimeter)) });
    skLineSegment(solenoidPlateSketchSk, "plate_right", { "start" : vector(definition.collarDepth, definition.blockHeight - (0.5 * millimeter)), "end" : vector(definition.collarDepth, definition.plateTop) });
    skLineSegment(solenoidPlateSketchSk, "plate_top", { "start" : vector(definition.collarDepth, definition.plateTop), "end" : vector(definition.collarDepth - definition.plateThickness, definition.plateTop) });
    skLineSegment(solenoidPlateSketchSk, "plate_left", { "start" : vector(definition.collarDepth - definition.plateThickness, definition.plateTop), "end" : vector(definition.collarDepth - definition.plateThickness, definition.blockHeight - (0.5 * millimeter)) });
    skSolve(solenoidPlateSketchSk);
    // Solenoid plate
    opExtrude(context, id + "solenoidPlate" + "tool", { "entities" : qSketchRegion(id + "solenoidPlateSketch"), "direction" : vector(1, 0, 0), "endBound" : BoundingType.BLIND, "endDepth" : definition.blockWidth / 2, "startBound" : BoundingType.BLIND, "startDepth" : definition.blockWidth / 2 });
    opBoolean(context, id + "solenoidPlate" + "bool", { "tools" : qUnion([qSubtraction(qCreatedBy(id + "collar", EntityType.BODY), qCreatedBy(id + "solenoidPlate" + "tool", EntityType.BODY)), qCreatedBy(id + "solenoidPlate" + "tool", EntityType.BODY)]), "operationType" : BooleanOperationType.UNION });
    // Bore split and plate holes sketch
    var boreSplitAndPlateHolesSketchSk = newSketchOnPlane(context, id + "boreSplitAndPlateHolesSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skCircle(boreSplitAndPlateHolesSketchSk, "bore", { "center" : vector(0, 0) * millimeter, "radius" : definition.boreDiameter / 2 });
    skLineSegment(boreSplitAndPlateHolesSketchSk, "split_bottom", { "start" : vector(-definition.earLength - (1 * millimeter), -definition.splitWidth / 2), "end" : vector((0 * millimeter), -definition.splitWidth / 2) });
    skLineSegment(boreSplitAndPlateHolesSketchSk, "split_right", { "start" : vector((0 * millimeter), -definition.splitWidth / 2), "end" : vector((0 * millimeter), definition.splitWidth / 2) });
    skLineSegment(boreSplitAndPlateHolesSketchSk, "split_top", { "start" : vector((0 * millimeter), definition.splitWidth / 2), "end" : vector(-definition.earLength - (1 * millimeter), definition.splitWidth / 2) });
    skLineSegment(boreSplitAndPlateHolesSketchSk, "split_left", { "start" : vector(-definition.earLength - (1 * millimeter), definition.splitWidth / 2), "end" : vector(-definition.earLength - (1 * millimeter), -definition.splitWidth / 2) });
    skCircle(boreSplitAndPlateHolesSketchSk, "plateHoleUpper", { "center" : vector((9.1 * millimeter), definition.solenoidHeight + (8 * millimeter)), "radius" : definition.plateHoleDiameter / 2 });
    skCircle(boreSplitAndPlateHolesSketchSk, "plateHoleLower", { "center" : vector(-(9.1 * millimeter), definition.solenoidHeight - (8 * millimeter)), "radius" : definition.plateHoleDiameter / 2 });
    skSolve(boreSplitAndPlateHolesSketchSk);
    // Bore split and plate holes
    opExtrude(context, id + "boreSplitAndPlateHoles" + "tool", { "entities" : qSketchRegion(id + "boreSplitAndPlateHolesSketch"), "direction" : vector(-0, 1, -0), "endBound" : BoundingType.THROUGH_ALL });
    opBoolean(context, id + "boreSplitAndPlateHoles" + "bool", { "tools" : qCreatedBy(id + "boreSplitAndPlateHoles" + "tool", EntityType.BODY), "targets" : qSubtraction(qCreatedBy(id + "collar", EntityType.BODY), qCreatedBy(id + "boreSplitAndPlateHoles" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // Tap and clamp hole sketch
    var tapAndClampHoleSketchSk = newSketchOnPlane(context, id + "tapAndClampHoleSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(tapAndClampHoleSketchSk, "tapHole", { "center" : vector((0 * millimeter), definition.collarDepth / 2), "radius" : definition.tapHoleDiameter / 2 });
    skCircle(tapAndClampHoleSketchSk, "clampHole", { "center" : vector(-definition.clampHoleOffset, definition.collarDepth / 2), "radius" : definition.clampHoleDiameter / 2 });
    skSolve(tapAndClampHoleSketchSk);
    // Tap and clamp holes
    opExtrude(context, id + "tapAndClampHoles" + "tool", { "entities" : qSketchRegion(id + "tapAndClampHoleSketch"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.THROUGH_ALL, "startBound" : BoundingType.BLIND, "startDepth" : definition.earHeight / 2 + (1 * millimeter) });
    opBoolean(context, id + "tapAndClampHoles" + "bool", { "tools" : qCreatedBy(id + "tapAndClampHoles" + "tool", EntityType.BODY), "targets" : qSubtraction(qCreatedBy(id + "collar", EntityType.BODY), qCreatedBy(id + "tapAndClampHoles" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // Pocket floor plane
    // Keyhole pocket sketch
    var keyholePocketSketchSk = newSketchOnPlane(context, id + "keyholePocketSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter + (definition.tabLength - definition.pocketDepth) * vector(1, 0, 0), vector(1, 0, 0), vector(0, 1, 0)) });
    skCircle(keyholePocketSketchSk, "seat", { "center" : vector(definition.collarDepth / 2, (0 * millimeter)), "radius" : definition.pocketDiameter / 2 });
    skLineSegment(keyholePocketSketchSk, "slot_bottom", { "start" : vector(definition.collarDepth / 2 - (2 * millimeter), -definition.tabHeight / 2 - (1 * millimeter)), "end" : vector(definition.collarDepth / 2 + (2 * millimeter), -definition.tabHeight / 2 - (1 * millimeter)) });
    skLineSegment(keyholePocketSketchSk, "slot_right", { "start" : vector(definition.collarDepth / 2 + (2 * millimeter), -definition.tabHeight / 2 - (1 * millimeter)), "end" : vector(definition.collarDepth / 2 + (2 * millimeter), definition.tabHeight / 2 + (1 * millimeter)) });
    skLineSegment(keyholePocketSketchSk, "slot_top", { "start" : vector(definition.collarDepth / 2 + (2 * millimeter), definition.tabHeight / 2 + (1 * millimeter)), "end" : vector(definition.collarDepth / 2 - (2 * millimeter), definition.tabHeight / 2 + (1 * millimeter)) });
    skLineSegment(keyholePocketSketchSk, "slot_left", { "start" : vector(definition.collarDepth / 2 - (2 * millimeter), definition.tabHeight / 2 + (1 * millimeter)), "end" : vector(definition.collarDepth / 2 - (2 * millimeter), -definition.tabHeight / 2 - (1 * millimeter)) });
    skSolve(keyholePocketSketchSk);
    // Keyhole pocket
    opExtrude(context, id + "keyholePocket" + "tool", { "entities" : qSketchRegion(id + "keyholePocketSketch"), "direction" : vector(1, 0, 0), "endBound" : BoundingType.THROUGH_ALL });
    opBoolean(context, id + "keyholePocket" + "bool", { "tools" : qCreatedBy(id + "keyholePocket" + "tool", EntityType.BODY), "targets" : qSubtraction(qCreatedBy(id + "collar", EntityType.BODY), qCreatedBy(id + "keyholePocket" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // remove the construction sketches and curves
    opDeleteBodies(context, id + "cleanupSketches", { "entities" : qUnion([qCreatedBy(id + "collarSketch", EntityType.BODY), qCreatedBy(id + "solenoidPlateSketch", EntityType.BODY), qCreatedBy(id + "boreSplitAndPlateHolesSketch", EntityType.BODY), qCreatedBy(id + "tapAndClampHoleSketch", EntityType.BODY), qCreatedBy(id + "keyholePocketSketch", EntityType.BODY)]) });
    });
